#!/usr/bin/env python3\n\"\"\"\nAURA API Server\nAPI REST para AURA IA\n\"\"\"\n\nimport os\nfrom datetime import datetime\nfrom flask import Flask, request, jsonify\nfrom flask_cors import CORS\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nfrom aura.core import AURA\n\napp = Flask(__name__)\nCORS(app)\n\n# Inicializa AURA\naura = AURA()\n\n# Variáveis globais\nusuarios = {}\n\n\n@app.route(\"/\", methods=[\"GET\"])\ndef index():\n    \"\"\"Rota raiz\"\"\"\n    return jsonify({\n        \"nome\": \"AURA IA\",\n        \"versao\": \"1.0.0\",\n        \"descricao\": \"Assistente Inteligente Completo\",\n        \"status\": \"✅ Online\",\n        \"endpoints\": {\n            \"chat\": \"POST /api/chat\",\n            \"sentimento\": \"POST /api/sentimento\",\n            \"health\": \"GET /api/health\"\n        }\n    })\n\n\n@app.route(\"/api/health\", methods=[\"GET\"])\ndef health():\n    \"\"\"Verifica a saúde da API\"\"\"\n    return jsonify({\n        \"status\": \"✅ Saudável\",\n        \"timestamp\": datetime.now().isoformat(),\n        \"provider\": aura.provider\n    })\n\n\n@app.route(\"/api/chat\", methods=[\"POST\"])\ndef chat():\n    \"\"\"Chat com AURA\"\"\"\n    try:\n        dados = request.get_json()\n        \n        if not dados or \"mensagem\" not in dados:\n            return jsonify({\"erro\": \"Campo 'mensagem' é obrigatório\"}), 400\n        \n        mensagem = dados[\"mensagem\"]\n        usuario_id = dados.get(\"usuario_id\", \"anonimo\")\n        \n        if not mensagem.strip():\n            return jsonify({\"erro\": \"Mensagem não pode estar vazia\"}), 400\n        \n        resposta = aura.chat(mensagem)\n        \n        if usuario_id not in usuarios:\n            usuarios[usuario_id] = []\n        \n        usuarios[usuario_id].append({\n            \"timestamp\": datetime.now().isoformat(),\n            \"mensagem\": mensagem,\n            \"resposta\": resposta\n        })\n        \n        return jsonify({\n            \"sucesso\": True,\n            \"resposta\": resposta,\n            \"timestamp\": datetime.now().isoformat()\n        })\n    \n    except Exception as e:\n        return jsonify({\"erro\": str(e)}), 500\n\n\n@app.route(\"/api/sentimento\", methods=[\"POST\"])\ndef analisar_sentimento():\n    \"\"\"Analisa sentimento\"\"\"\n    try:\n        dados = request.get_json()\n        \n        if not dados or \"texto\" not in dados:\n            return jsonify({\"erro\": \"Campo 'texto' é obrigatório\"}), 400\n        \n        texto = dados[\"texto\"]\n        resultado = aura.analisar_sentimento(texto)\n        \n        return jsonify({\n            \"sucesso\": True,\n            \"analise\": resultado,\n            \"timestamp\": datetime.now().isoformat()\n        })\n    \n    except Exception as e:\n        return jsonify({\"erro\": str(e)}), 500\n\n\nif __name__ == \"__main__\":\n    host = os.getenv(\"SERVER_HOST\", \"0.0.0.0\")\n    port = int(os.getenv(\"SERVER_PORT\", 5000))\n    debug = os.getenv(\"FLASK_DEBUG\", \"False\").lower() == \"true\"\n    \n    print(\"\\n\" + \"=\"*60)\n    print(\"🌟 AURA IA - REST API\".center(60))\n    print(\"=\"*60)\n    print(f\"\\n🚀 Servidor em: http://{host}:{port}\")\n    print(f\"📊 Provider: {aura.provider}\")\n    print(f\"🤖 Modelo: {aura.model}\\n\")\n    print(\"=\"*60 + \"\\n\")\n    \n    app.run(host=host, port=port, debug=debug)